 document.addEventListener('DOMContentLoaded', () => {
     const form = document.getElementById('contact-form');
     const statusRegion = document.getElementById('form-status');

     const fields = {
         fullName: {
             input: document.getElementById('full-name'),
             error: document.getElementById('full-name-error'),
             validate: (value) => value.trim().length > 0
         },
         email: {
             input: document.getElementById('email'),
             error: document.getElementById('email-error'),
             validate: (value) => {
                 const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
                 return emailRegex.test(value);
             }
         },
         phone: {
             input: document.getElementById('phone'),
             error: document.getElementById('phone-error'),
             validate: (value) => {
                 if (!value) return true; // Optional
                 // Simple regex for phone numbers - could be more complex
                 const phoneRegex = /^\+?[\d\s-]{7,15}$/;
                 return phoneRegex.test(value);
             }
         }
     };

     const validateField = (fieldKey) => {
         const field = fields[fieldKey];
         const isValid = field.validate(field.input.value);

         if (isValid) {
             field.input.setAttribute('aria-invalid', 'false');
             field.error.hidden = true;
         } else {
             field.input.setAttribute('aria-invalid', 'true');
             field.error.hidden = false;
         }
         return isValid;
     };

     // Real-time validation
     Object.keys(fields).forEach(key => {
         fields[key].input.addEventListener('blur', () => validateField(key));
         fields[key].input.addEventListener('input', () => {
             if (fields[key].input.getAttribute('aria-invalid') === 'true') {
                 validateField(key);
             }
         });
     });

     form.addEventListener('submit', (e) => {
         e.preventDefault();

         let firstInvalidField = null;
         let isFormValid = true;

         Object.keys(fields).forEach(key => {
             const isValid = validateField(key);
             if (!isValid) {
                 isFormValid = false;
                 if (!firstInvalidField) {
                     firstInvalidField = fields[key].input;
                 }
             }
         });

         if (isFormValid) {
             // Mock submission
             statusRegion.textContent = 'Message sent successfully! We will get back to you soon.';
             form.reset();
             // Reset aria-invalid attributes
             Object.keys(fields).forEach(key => {
                 fields[key].input.setAttribute('aria-invalid', 'false');
                 fields[key].error.hidden = true;
             });
         } else {
             statusRegion.textContent = ''; // Clear success message if it exists
             if (firstInvalidField) {
                 firstInvalidField.focus();
             }
         }
     });
 });

