                <label for="phone">Phone number (optional)</label>
                <input type="tel" id="phone" name="phone" autocomplete="tel" aria-describedby="phone-help phone-error">
                <p id="phone-help" class="help-text">Expected format: +1-555-555-5555</p>
                <p id="phone-error" class="error-message" hidden>Error: Enter a valid phone number (e.g., +1-555-555-5555) or leave blank.</p>
            </div>

